const fmt=n=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:0}).format(Number(n)||0);
const peso=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(Number(n)||0);
const pesoDia=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0);
const groups=[['territorio','1 · Panorama y territorio',Map],['educacion','2 · Estudiantes y oferta',GraduationCap],['costos','3 · Economía y financiación',Wallet],['empleo','4 · Empleo y personas',BriefcaseBusiness],['cultura','5 · Cultura y regulación',Library]];
const grupos=groups.map(([group,label,Icon])=>[modulos.find(x=>x.grupo===group).clave,label,Icon,modulos.filter(x=>x.grupo===group).map(x=>x.clave)]);
